import { prisma } from '@/lib/prisma';

async function registerUserWithContent() {
  return await prisma.user.create({
    data: {
      email: 'alex.rivera@example.com',
      name: 'Alex Rivera',
      profile: {
        create: {
          bio: 'Fullstack Software Engineer',
          avatarUrl: 'https://images.example.com/avatar.jpg',
        }
      },
      posts: {
        create: [
          { title: 'Getting Started with Next.js 15', content: 'Modern fullstack architecture...' },
          { title: 'Prisma Client Deep Dive', content: 'Understanding nested writes...' }
        ]
      }
    },
    include: {
      profile: true,
      posts: true
    }
  });
}

const syncedUser = await prisma.user.upsert({
  where: { email: 'oauth_user@gmail.com' },
  update: {
    lastLoginAt: new Date(),
    avatarUrl: 'https://lh3.googleusercontent.com/...'
  },
  create: {
    email: 'oauth_user@gmail.com',
    name: 'Google User',
    avatarUrl: 'https://lh3.googleusercontent.com/...'
  }
});
